    result = {"candidate_imports": 0, "call_phase_reports": 0, "test_bodies_observed": None,
              "body_count_limitation": "Actual call-phase reports retained; no separate test-function entry tracer.", "collection_reached": False,
              "collected": None, "passed": 0, "failed": 0, "errors": 0, "skipped": 0,
              "xfailed": 0, "xpassed": 0, "incomplete": 0, "actual_contexts": 0,
              "actual_OS_backend_calls_observed": None, "source_acceptance": False,
              "OS_backend_count_limitation": "No native-call tracer; frozen tests use explicit inert observations. Static scope only.",
              "operational_qualification": False, "product_acceptance": False}
    started = time.monotonic()
